    internal class UnionAnyConverter : JsonConverter
    {
        public override bool CanConvert(Type t) => t == typeof(UnionAny) || t == typeof(UnionAny?);

        public override object ReadJson(JsonReader reader, Type t, object existingValue, JsonSerializer serializer)
        {
            switch (reader.TokenType)
            {
                case JsonToken.Integer:
                case JsonToken.Float:
                    var doubleValue = serializer.Deserialize<double>(reader);
                    return new UnionAny { Double = doubleValue };
                case JsonToken.StartObject:
                    var objectValue = serializer.Deserialize<Any>(reader);
                    return new UnionAny { Any = objectValue };
            }
            throw new Exception("Cannot unmarshal type UnionAny");
        }

        public override void WriteJson(JsonWriter writer, object untypedValue, JsonSerializer serializer)
        {
            var value = (UnionAny)untypedValue;
            if (value.Double != null)
            {
                serializer.Serialize(writer, value.Double.Value);
                return;
            }
            if (value.Any != null)
            {
                serializer.Serialize(writer, value.Any);
                return;
            }
            throw new Exception("Cannot marshal type UnionAny");
        }

        public static readonly UnionAnyConverter Singleton = new UnionAnyConverter();
    }

